<?php declare(strict_types=1); namespace App\Domains\WorkCore\System\Modules\Reviews\Actions; use App\Domains\WorkCore\System\Actions\{ActionHandlerResult,ActionRequest,PendingDomainEvent}; use App\Domains\WorkCore\System\Actions\Contracts\BusinessActionHandlerContract; use App\Domains\WorkCore\System\Modules\Reviews\Contracts\ReviewRepositoryContract; use App\Domains\WorkCore\System\References\TypedReference; final class PublishReview implements BusinessActionHandlerContract { public function __construct(private ReviewRepositoryContract $repository){} public function handle(ActionRequest $r): ActionHandlerResult {$x=$this->repository->publish((string)$r->payload['review_public_id'],$r->payload,$r->companyId,$r->actorId);return new ActionHandlerResult($x,new TypedReference('review',(string)$x['public_id']),[new PendingDomainEvent('workcore.review.publication.changed',1,['review'=>$x])]);}}
